// ✅ 按渲染逻辑分组
public override void OnGUI(MaterialEditor editor, MaterialProperty[] props)
{
    // 第一层：主贴图与颜色
    EditorGUILayout.BeginVertical(EditorStyles.helpBox);
    MaterialEditor.TextureProperty("_MainTex");
    MaterialEditor.ColorProperty("_Color");
    EditorGUILayout.EndVertical();

    // 第二层：光照参数
    EditorGUILayout.BeginVertical(EditorStyles.helpBox);
    MaterialEditor.RangeProperty("_Glossiness");
    MaterialEditor.RangeProperty("_Metallic");
    EditorGUILayout.EndVertical();
}

// ✅ 智能联动：Enum 切换控制参数组显隐
bool useRamp = (_RampMode.floatValue == 1);
EditorGUILayout.BeginFadeGroup(ref useRamp);
{
    MaterialEditor.TextureProperty("_RampTex");
    MaterialEditor.ColorProperty("_RampColor");
}
EditorGUILayout.EndFadeGroup();

// ✅ 安全禁用：参数存在但当前配置不适用
using (new EditorGUILayout.DisabledScope(!useRamp))
{
    MaterialEditor.RangeProperty("_RampBlend", "Ramp 混合");
}

public static class ShaderGUIUtil
{
    public static void DrawProp(MaterialProperty prop, string label)
    {
        if (prop == null) return;
        EditorGUILayout.PropertyField(prop, new GUIContent(label));
    }

    public static void DrawTex(MaterialProperty tex, string label)
    {
        if (tex == null) return;
        editor.TextureProperty(tex, label);
    }

    public static void BeginGroup(string title)
    {
        EditorGUILayout.BeginVertical("box");
        EditorGUILayout.LabelField(title, EditorStyles.boldLabel);
    }

    public static void EndGroup()
    {
        EditorGUILayout.EndVertical();
    }
}
